glsl4.vert:
precision highp float;
layout(set = 0, binding = 0) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(set = 0, binding = 1) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(set = 2, binding = 0) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
  highp vec4 cc_reflectionProbeData1;
  highp vec4 cc_reflectionProbeData2;
  highp vec4 cc_reflectionProbeBlendData1;
  highp vec4 cc_reflectionProbeBlendData2;
};
layout(location = 0) in vec3 a_position;
layout(location = 1) in vec2 a_uv0;
layout(location = 2) in vec4 a_color;
layout(location = 0) out vec2 v_uv;
layout(location = 1) out vec4 v_color;
void main () {
  v_uv = a_uv0;
  v_color = a_color;
  gl_Position = cc_matViewProj * cc_matWorld * vec4(a_position, 1.0);
}

glsl4.frag:
precision highp float;
layout(location = 0) in vec2 v_uv;
layout(location = 1) in vec4 v_color;
layout(set = 1, binding = 1) uniform sampler2D mainTexture;
layout(set = 1, std140, binding = 0) uniform Constant {
  vec4 glowColor;
  float glowStrength;
  float edgeGlow;
  float shimmerStrength;
  float rippleStrength;
  float noiseStrength;
  float neonWidth;
  float neonIntensity;
  float speed;
  float time;
};
layout(location = 0) out vec4 fragColor;
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x)
       + (c - a) * u.y * (1.0 - u.x)
       + (d - b) * u.x * u.y;
}
void main () {
  vec2 uv = v_uv;
  vec2 centered = uv - vec2(0.5);
  float dist = length(centered);
  float ripple = sin(dist * 20.0 - time * 4.0 * speed) * rippleStrength;
  vec2 warpedUV = uv + centered * ripple * 0.08;
  vec4 tex = texture(mainTexture, warpedUV) * v_color;
  if (tex.a <= 0.001) {
    discard;
  }
  float shimmer = sin((uv.x + uv.y) * 12.0 - time * 5.0 * speed) * shimmerStrength;
  float n = noise(uv * 6.0 + time * 0.8 * speed) * noiseStrength;
  float glowPulse = 0.5 + 0.5 * sin(time * 3.0 * speed);
  float innerGlowMask = 1.0 - smoothstep(0.18, 0.5, dist);
  float ringMask = smoothstep(0.5 - neonWidth, 0.5, dist) * (1.0 - smoothstep(0.5, 0.5 + 0.02, dist));
  float outerEdge = smoothstep(0.38, 0.5, dist);
  float glow = glowStrength * glowPulse + shimmer + n;
  float neonPulse = 0.75 + 0.25 * sin(time * 6.0 * speed);
  vec3 emissive =
      glowColor.rgb * glow * innerGlowMask * 1.6 +
      glowColor.rgb * ringMask * neonIntensity * neonPulse +
      glowColor.rgb * outerEdge * edgeGlow * 0.7;
  vec3 finalRgb = tex.rgb + emissive * tex.a;
  fragColor = vec4(finalRgb, tex.a);
}

